<?php
declare(strict_types=1);
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Fleet locations | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"><script src="/assets/js/vehicles.js" defer></script></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/fleet/vehicles">Fleet</a><a href="/fleet/locations">Locations</a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Fleet setup</p><h1>Vehicle locations</h1><p>Retired locations are hidden from new selections and remain in historical records. Removal is reserved for unused, retired locations.</p></div></section><form class="panel inline-form" method="post" action="/fleet/locations/create"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label>New location <input name="name" maxlength="120" required></label><button type="submit">Add location</button></form><section class="panel"><div class="table-wrap"><table><thead><tr><th>Location</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($locations as $loc):?><tr><td><?= $e($loc['name']) ?></td><td><?= $e($loc['location_status']) ?></td><td><?= $e($loc['created_at']) ?></td><td><?php if($loc['location_status']==='active'):?><form method="post" action="/fleet/locations/retire" data-confirm="Retire this location? Historical references will remain valid."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="location_id" value="<?= (int)$loc['location_id'] ?>"><button type="submit">Retire</button></form><?php endif;?><?php if($user['role']==='system_admin' && $loc['location_status']==='retired'):?><form method="post" action="/fleet/locations/remove" data-confirm="Remove this unused retired location? Referenced locations cannot be removed."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="location_id" value="<?= (int)$loc['location_id'] ?>"><button class="button-danger" type="submit">Remove</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$locations):?><tr><td colspan="4">No locations configured.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
